def nc(group,panel=0,reference='msecont',**conditions):
 for q in net['selected_comparisons'][group]:
  if q['reference']==reference and q['key'][0]==panel and all(q['key'][i]==v for i,v in conditions.items()):return q
 raise KeyError((group,panel,reference,conditions))
def blocks(text):
 out=[]
 for p in re.split(r'\n\s*\n',text.strip()):
  p=p.strip()
  if not p:continue
  kind='heading' if re.match(r'^\d+(\.\d+)?\.?(?:\s)',p) and '\n' not in p and len(p)<130 else 'paragraph'
  if p.startswith('[[EQ_'):kind='equation'
  out.append({'type':kind,'text':p})
 return out
def table(caption,headers,rows,note):return {'type':'table','caption':caption,'headers':headers,'rows':rows,'note':note}
