# References are numbered on first appearance; neither abstract-only reading nor unresolved author declarations are hidden.
refs={}
for p in [ROOT/'manuscript/references_verified.txt',R/'research/references_revision.txt']:
 for match in re.finditer(r'\[(L\d+)\]\s*(.*?)(?=\n\s*\[L\d+\]|\Z)',p.read_text(encoding='utf-8'),re.S):refs[match.group(1)]=' '.join(match.group(2).split())
used=[]
def remap(text):
 def f(match):
  keys=re.findall(r'L\d+',match.group())
  for k in keys:
   if k not in refs:raise KeyError(k)
   if k not in used:used.append(k)
  return '['+', '.join(str(used.index(k)+1) for k in keys)+']'
 return re.sub(r'\[L\d+(?:\s*,\s*L\d+)*\]',f,text)
for b in base:
 for k in ['text','caption','note']:
  if k in b:b[k]=remap(b[k])
base.append({'type':'heading','text':'References'})
for i,k in enumerate(used,1):base.append({'type':'reference','text':f'[{i}] {refs[k]}'})
out={'title':title,'target_journal':'Electric Power Systems Research','blocks':base,'reference_keys':used,'abstract_words':len(abstract.split())}
(M/'article_blocks.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
def plaintext(bs):
 eq={'[[EQ_BATTERY]]':'e_t = e_(t−1) + Δ(η c_t − d_t/η); 0 ≤ c_t,d_t ≤ 3; 1 ≤ e_t ≤ 9; e_0 = e_48 = 5. (1)', '[[EQ_OBJECTIVE]]':'J_hat = Δ Σ_t [p_buy,t max(g_hat,t,0) + p_sell,t min(g_hat,t,0) + κ(c_t+d_t)] + ε R(c,d,e). (2)', '[[EQ_SELECTION]]':'R(c,d,e) = Σ_t [(c_t/3)^2 + (d_t/3)^2 + (e_t/10)^2]. (3)', '[[EQ_DFL]]':'L_DFL(θ) = (1/N) Σ_i C_i[A_ε(l_hat,i − f_θ(x_i))]. (4)'}
 return '\n\n'.join(eq.get(b.get('text',''),b.get('text',b.get('caption','')))+ ('\n'+' | '.join(b['headers'])+'\n'+'\n'.join(' | '.join(str(x) for x in row) for row in b['rows'])+'\n'+b['note'] if b['type']=='table' else ('\n'+b['note'] if b['type']=='figure' else '')) for b in bs)
